  'Reports dependencies',
  (assert) => {
    const actual = new Set();

    jssLiteLoader.apply(mockLoaderApi({
      addDependency: dep => actual.add(dep),
    }), ['module.exports = { stylesheet: {} }']);

    const dependenciesPath =
      path.resolve(fixturesPath, 'dependencies');
